package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.SearchInterval;
import org.apache.commons.math3.optim.univariate.UnivariateRealOptimizer;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer#getResult.
 */
public class MultiStartUnivariateRealOptimizer_getResult_TriageGen2Test {

    private UnivariateRealOptimizer mockOptimizer;
    private JDKRandomGenerator randomGenerator;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        randomGenerator = new JDKRandomGenerator();
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 1, randomGenerator);
    }

    @Test
    public void testGetResultReturnsValueFromOptimizer() {
        // Arrange
        double expectedResult = 42.0;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = multiStartOptimizer.getResult();

        // Assert
        assertEquals("getResult should return the value provided by the underlying optimizer", expectedResult, actualResult, 1e-15);
    }

    @Test
    public void testGetResultReturnsNegativeValue() {
        // Arrange
        double expectedResult = -123.456;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = multiStartOptimizer.getResult();

        // Assert
        assertEquals("getResult should handle negative return values from the underlying optimizer", expectedResult, actualResult, 1e-15);
    }

    @Test
    public void testGetResultReturnsZero() {
        // Arrange
        double expectedResult = 0.0;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = multiStartOptimizer.getResult();

        // Assert
        assertEquals("getResult should handle zero return values", expectedResult, actualResult, 1e-15);
    }

    @Test
    public void testGetResultWithNaN() {
        // Arrange
        double expectedResult = Double.NaN;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = multiStartOptimizer.getResult();

        // Assert
        assertEquals("getResult should handle NaN return values", expectedResult, actualResult, 0.0);
    }

    @Test
    public void testGetResultWithInfinity() {
        // Arrange
        double expectedResult = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getResult()).thenReturn(expectedResult);

        // Act
        double actualResult = multiStartOptimizer.getResult();

        // Assert
        assertEquals("getResult should handle Infinity return values", expectedResult, actualResult, 0.0);
    }
}
